result:
    .itemOn{
        border-radius: 0!important
        img,.empty-box{
            border-radius: 0!important
        }
        .img-box{
            .label{
                border-radius: 0 0 8px 0!important
            }
        }
    }
    .pageOn{
		border-radius: 8px!important
	}
	.listCross{
		width: 100%;
		background: #fff;
		padding: 16px 12px 6px 12px;
		.item{
			width: 49%;
			margin-bottom: 10px;
			.pictrue{
				width: 72px;
				height: 72px;
				background: #F3F9FF;
				border-radius: 4px;
				margin-right: 10px;
				img {
					width: 26px;
					height: 20px;
					display: block;
				}
				.img {
					width: 100%;
					height: 100%;
					display: block;
					object-fit: cover;
				}
			}
			.text{
				flex: 1;
				.name{
					font-size: 13px;
					color: #282828;
					height: 45px;
				}
				.price{
					font-size: 18px;
					font-weight: 600;
					font-family: SemiBold;
					span {
						font-size: 12px;
					}
				}
			}
		}
	}
    .listBig{
		width: 100%;
		.itemBig{
			width: 100%;
			margin-bottom: 10px;
			background-color: #fff;
			border-radius: 10px;
			position: relative;
			.bnt {
				width: 48px;
				height: 28px;
				background: linear-gradient(90deg, #E93323 0%, #FF7931 100%);
				border-radius: 25px;
				text-align: center;
				line-height: 28px;
				font-size: 12px;
				color: #fff;
				position: absolute;
				right: 10px;
				bottom: 12px;
			}
			.jia{
				width: 22px;
				height: 22px;
				background-color: #E93323;
				border-radius: 50%;
				position: absolute;
				right: 10px;
				bottom: 10px;
				.jiaCon{
					width: 100%;
					height: 100%;
					text-align: center;
					line-height: 22px;
					.iconfont{
						color: #fff
						font-size: 13px
					}
				}
			}
			.conter{
				padding: 0 12px 12px 12px;
				&.on {
					height: 45px;
				}
				.name{
					margin-top: 10px;
					font-weight: 400;
					color: #333333;
					font-size: 14px;
					padding: 0;
				}
				img {
					width: 99px;
					height: 14px;
					display: block;
					margin-top: 5px;
				}
				.price{
					margin-top: 3px;
					img {
						width: 70px;
						height: 15px;
					}
					.num{
						font-size: 20px;
						font-family: SemiBold;
						span {
							font-size: 12px;
						}
					}
				}
				.bottom{
					font-weight: 400;
					color: #999999;
					font-size: 11px;
				}
			}
			.img-box{
				width: 100%;
				height: 180px;
				position: relative;

				img {
					width: 65px
					height: 50px
				}
				.img {
					width: 100%;
					height: 100%;
					object-fit: cover;
				}
				.empty-box{
					border-radius: 8px 8px 0 0;
					background: #F3F9FF;
				}
				.label{
					position: absolute
					top: 0;
					left:0;
					width:59px;
					height:25px;
					line-height: 25px
					text-align: center
					color: #fff
					font-size: 12px
					border-radius: 8px 0 8px 0
				}
			}
			.name{
				font-size: 15px;
				font-weight: bold;
				margin-top: 8px;
				padding: 0 10px;
			}
			.coupon{
				width:16px;
				height:18px;
				line-height: 18px
				text-align: center
				font-size: 12px
				margin-right: 5px;
				display: inline-block
			}
			.price{
				font-weight: bold
				font-size: 12px
				.num{
					font-size: 18px
					margin-right: 5px;
				}
			}
		}
	}
    .paddingBox{
		padding-bottom: 0
	}
    .home_product{
		overflow: hidden;
		.hd_nav{
			display: flex
			height: 65px
			padding: 0 5px
			.item{
				display: flex
				flex-direction: column
				justify-content: center
				width 25%
				.title{
					font-size: 16px
					color: #282828
				}
				.label{
					width:62px;
					height:18px;
					line-height: 18px
					text-align: center
					background:transparent;
					border-radius:8px;
					color: #999999
					font-size: 12px
				}
				&.active{
					.title{
						color: #FF4444
					}
					.label{
						color: #fff
						background:linear-gradient(270deg,rgba(255,84,0,1) 0%,rgba(255,0,0,1) 100%);
					}
				}
			}
		}
	}
        .list-wrapper{
			display: flex
			flex-wrap: wrap
			justify-content: space-between
			.item{
				width: 48.5%
				margin-bottom: 10px
				background-color: #fff
				position: relative;
				.bnt{
					width: 48px;
					height: 28px;
					background: linear-gradient(90deg, #E93323 0%, #FF7931 100%);
					border-radius: 25px;
					color: #fff;
					text-align: center;
					line-height: 28px;
					font-size: 12px;
					position: absolute;
					right: 10px;
					bottom: 10px;

				}
				.jia{
					width: 22px;
					height: 22px;
					background-color: #E93323;
					border-radius: 50%;
					position: absolute;
					right: 10px;
					bottom: 10px;
					.jiaCon{
						width: 100%;
						height: 100%;
						text-align: center;
						line-height: 22px;
						.iconfont{
							color: #fff;
							font-size: 13px;
						}
					}
				}
				.img-box{
					position: relative
					width: 100%
					height: 173px
					.img{
						width: 100%;
						height: 100%;
						object-fit: cover;
					}
					img,.box{
						width: 65px
						height: 50px
					}
					.empty-box{
						background:  #F3F9FF
					}
					.box{
						background: #D8D8D8
					}
					.label{
						position: absolute
						left: 0
						top: 0
						width:46px;
						height:22px;
						border-radius:10px 0px 10px 0px;
						color: #fff
						font-size: 13px
						text-align: center
						line-height: 22px
					}
				}
				.info{
					padding: 7px 10px
					.title{
						font-size: 14px
						color: #333
					}
					img {
						width: 99px;
						height: 14px;
						display: block;
						margin-top: 4px;
					}
					.bottom {
						color: #999999;
						font-size: 11px;
					}
					.price{
						display: flex
						align-items: center
						img {
							width: 70px;
							height: 15px;
							display: block;
						}
						.num{
							font-size: 20px
							margin-right: 4px
							font-family: SemiBold;
							span{
								font-size: 12px
							}
						}
						.label{
							width:16px;
							height:18px;
							margin-left: 5px
							text-align: center
							line-height: 18px
							font-size: 11px
							&.on{
								margin-left: 0
							}
						}
					}
				}
			}
		}


            &.itemA{
				/*background #fff*/
				.item{
					display: flex
					width: 100%
					padding: 10px;
					position: relative;

					.img-box{
						position: relative
						width: 112px
						height: 112px
						img {
							width: 65px;
							height: 50px;
						}
						.empty-box{
							background: #F3F9FF
						}
					}

					.info{
						display: flex
						justify-content: space-between
						flex-direction: column
						flex: 1
						margin-left: 10px
						padding: 0;
						.hd{
							height: 63px;
						}
						.price{
							margin-top: 2px;
							&.on{
								margin-top: 20px;
							}
							.img{
								margin-top: 0;
							}
						}
					}
				}
			}
            &.itemB{
				justify-content: inherit;
				background-color: #fff;
				padding: 16px 10px 0 10px;
				width: 100%;
				box-sizing: border-box;

				.list{
					display: flex;
					flex-wrap: wrap;
				}

				.item{
					width: 31.3%
					margin-right: 10px
					background: unset;
					.jia{
						right: 2px;
						bottom: 0;
					}
					.info{
						padding: 0;
						&.on {
							height: 70px;
						}
						&.on2{
							height: 30px;
						}
						.hd{
							margin-top: 7px;
							height: 42px;
						}
						.price{
							margin-top: 7px;
							line-height: 1.2;
						}
					}
					&:nth-child(3n){
						margin-right: 0
					}
					.img-box{
						position: relative
						width: 100%
						height: 110px
						img,.box,.empty-box{
							border-radius:10px 10px 0 0;
						}
					}
				}
			}
			&.itemD{
				flex-wrap: nowrap;
				display: inline-flex;
				overflow: hidden;
				.list{
					flex-wrap: nowrap;
					justify-content: center;
					align-items: center;
				}
				.item{
					width: 100px;
					background: unset;
					&:nth-child(3n){
						margin-right: 10px
					}
					.img-box{
						height: 100px;
					}
				}
			}
			&.itemC{
				.item .info.on{
					height: 67px;
				}
				.item .info.on2{
					height: 40px;
				}
				.item .info .price{
					margin-top: 6px;
				}
				.item .info .bottom{
					margin-top: 3px;
				}
			}
